#include <iostream>
#include <string>

int main() {
    std::string st;
    std::getline(std::cin, st);
    char first_char = st[0];
    std::string rest = st.substr(1);
    size_t pos;
    while ((pos = rest.find("dot")) != std::string::npos) {
        rest.replace(pos, 3, ".");
    }
    std::string result = first_char + rest;
    if (!result.empty() && result.back() == '.') {
        result.back() = 't'; // temporarily replace '.' with 't'
        result += "dot"; // append 'dot' to the end
        result.pop_back(); // remove the 't' to replace the '.' with 'dot'
        result.back() = 't'; // restore the last character to 't'
        result.replace(result.size() - 3, 3, "dot");
    }
    first_char = result[0];
    rest = result.substr(1);
    size_t at_pos = rest.find("at");
    if (at_pos != std::string::npos) {
        rest.replace(at_pos, 2, "@");
    }
    if (!rest.empty() && rest.back() == '@') {
        rest.back() = 't'; // temporarily replace '@' with 't'
        rest += "at"; // append 'at'
        rest.pop_back(); // remove the 't' to replace '@' with 'at'
        rest.back() = 't'; // restore the last character to 't'
        rest.replace(rest.size() - 2, 2, "at");
    }
    std::cout << first_char + rest << std::endl;
    return 0;
}

